from typing import List

class Solution:
    def minTime(self, skill: List[int], mana: List[int]) -> int:
        n = len(skill)
        m = len(mana)

        # Prefix sums of skill: P[i] = skill[0] + ... + skill[i-1]
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + skill[i]

        # Build the lower convex hull for the points (X_i, Y_i) = (P[i+1], P[i])
        # Since X_i is strictly increasing, we can just process them in order.
        hull = []
        for i in range(n):
            p = (P[i + 1], P[i])
            while len(hull) >= 2:
                p1 = hull[-2]
                p2 = hull[-1]

                # Cross product to check if it's a strictly left (counter-clockwise) turn
                v1_x = p2[0] - p1[0]
                v1_y = p2[1] - p1[1]
                v2_x = p[0] - p2[0]
                v2_y = p[1] - p2[1]

                if v1_x * v2_y - v1_y * v2_x <= 0:
                    hull.pop()
                else:
                    break
            hull.append(p)

        start = 0
        for j in range(m - 1):
            x = mana[j]
            y = mana[j + 1]

            # Binary search to find the point on the lower hull that maximizes:
            # f(X, Y) = X * x - Y * y
            # Because we use the lower hull, the sequence of slopes is strictly increasing.
            low = 0
            high = len(hull) - 2
            ans_idx = len(hull) - 1

            while low <= high:
                mid = (low + high) // 2
                dy = hull[mid + 1][1] - hull[mid][1]
                dx = hull[mid + 1][0] - hull[mid][0]

                # We want the first index where the slope (dy / dx) >= x / y
                # Since dx > 0 and y > 0, we can cross-multiply to avoid floats:
                if y * dy >= x * dx:
                    ans_idx = mid
                    high = mid - 1
                else:
                    low = mid + 1

            best = hull[ans_idx][0] * x - hull[ans_idx][1] * y
            start += best

        return start + P[n] * mana[-1]
